import{_ as t,o,c as a,ao as r}from"./chunks/framework.C8GYkrKD.js";const p=JSON.parse('{"title":"GPU compatibility","description":"","frontmatter":{},"headers":[],"relativePath":"compatibility/gpu.md","filePath":"compatibility/gpu.md","lastUpdated":null}'),d={name:"compatibility/gpu.md"};function i(n,e,l,c,s,h){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="GPU-compatibility" tabindex="-1">GPU compatibility <a class="header-anchor" href="#GPU-compatibility" aria-label="Permalink to &quot;GPU compatibility {#GPU-compatibility}&quot;">​</a></h1><p>This page is a <strong>compatibility reference</strong> for running a <code>Flow</code> on a GPU device (<code>CuArray</code> state). It complements the <a href="./../flows/gpu">GPU flows</a> guide, which covers the <em>why</em> and the <em>contract</em> (no scalar indexing, <code>method=:gpu</code>, AD backend selection) — this page is the compact, per-constructor and per-AD-backend <strong>table</strong>, plus a few refinements found while re-measuring for this page.</p><div class="warning custom-block"><p class="custom-block-title">Last probed: 2026-07-23 — not build-executed</p><p>Unlike the 8 CPU pages, this page is not self-verifying: the code blocks below are <strong>illustrative</strong> <code>julia</code> blocks, not <code>@example</code>/<code>@repl</code> — there is no GPU device in the Documenter build (nor on the machine this page was written on). Every ✓/✗ is instead sourced from a <strong>measured run</strong> of <a href="https://github.com/control-toolbox/CTFlows.jl/blob/main/probe/gpu/probe_gpu.jl" target="_blank" rel="noreferrer"><code>probe/gpu/probe_gpu.jl</code></a> on the self-hosted NVIDIA (<code>kkt</code>) runner — <a href="https://github.com/control-toolbox/CTFlows.jl/actions/runs/30037105763/job/89317162708" target="_blank" rel="noreferrer">run 30037105763</a>, 2026-07-23 — triggered specifically for this page, not carried over from an older document. Re-run the probe (<code>run probe</code> label on a PR) to re-verify; this page can drift from the code between probe runs in a way the CPU pages structurally cannot.</p></div><p>Scope: <strong>NVIDIA/CUDA</strong>, validated via CUDA.jl. AMDGPU/Metal are untested (see <a href="./../flows/gpu">GPU flows</a>).</p><hr><h2 id="Per-constructor-table" tabindex="-1">Per-constructor table <a class="header-anchor" href="#Per-constructor-table" aria-label="Permalink to &quot;Per-constructor table {#Per-constructor-table}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Flow source</th><th style="text-align:right;">AD needed</th><th style="text-align:right;">Device call</th><th style="text-align:right;">This run</th></tr></thead><tbody><tr><td style="text-align:right;"><code>Flow(::VectorField)</code></td><td style="text-align:right;">no</td><td style="text-align:right;">pass <code>CuArray</code>s</td><td style="text-align:right;">✓ re-verified (point + trajectory)</td></tr><tr><td style="text-align:right;"><code>Flow(::HamiltonianVectorField)</code></td><td style="text-align:right;">no</td><td style="text-align:right;">pass <code>CuArray</code>s</td><td style="text-align:right;">✓ re-verified (point)</td></tr><tr><td style="text-align:right;"><code>Flow(::ODEFunction)</code></td><td style="text-align:right;">no</td><td style="text-align:right;">pass <code>CuArray</code>s</td><td style="text-align:right;">not in this probe — same no-AD mechanism as <code>Flow(VectorField)</code>, see <a href="./sciml"><code>Flow(SciML)</code></a></td></tr><tr><td style="text-align:right;"><code>Flow(::ODEProblem)</code></td><td style="text-align:right;">no</td><td style="text-align:right;">pass <code>CuArray</code>s</td><td style="text-align:right;">✓ re-verified (point remake)</td></tr><tr><td style="text-align:right;"><code>Flow(ocp)</code> — state flow (no costate)</td><td style="text-align:right;">no</td><td style="text-align:right;">pass <code>CuArray</code>s</td><td style="text-align:right;">not re-tested this run — carried from prior validation, see <a href="/CTFlows.jl/previews/PR364/flows/gpu#What-runs-on-device">GPU flows</a></td></tr><tr><td style="text-align:right;"><code>Flow(ocp, OpenLoop/ClosedLoop)</code></td><td style="text-align:right;">no</td><td style="text-align:right;">pass <code>CuArray</code>s</td><td style="text-align:right;">not re-tested this run — carried from prior validation</td></tr><tr><td style="text-align:right;"><code>Flow(::Hamiltonian)</code></td><td style="text-align:right;">yes</td><td style="text-align:right;"><code>method=:gpu</code> (swaps the default AD backend — see below)</td><td style="text-align:right;">✓ re-verified: default backend fails (scalar indexing, expected), <code>AutoZygote</code>/<code>AutoMooncake</code> both work</td></tr><tr><td style="text-align:right;"><code>Flow(ocp)</code> — Hamiltonian (with costate) / <code>Flow(ocp, DynClosedLoop)</code></td><td style="text-align:right;">yes</td><td style="text-align:right;"><code>method=:gpu</code></td><td style="text-align:right;">✓ re-verified — <strong>only <code>AutoMooncake</code> survives</strong> the in-place OCP dynamics on device (see backend table)</td></tr><tr><td style="text-align:right;">Multi-phase concatenation (<code>*</code>), with jumps</td><td style="text-align:right;">inherits</td><td style="text-align:right;">works on device</td><td style="text-align:right;">not re-tested this run — carried from prior validation</td></tr><tr><td style="text-align:right;"><code>variable_costate=true</code></td><td style="text-align:right;">yes</td><td style="text-align:right;">explicit <code>ad_backend=AutoZygote()</code>, host or device <code>variable</code>, any length</td><td style="text-align:right;">✓ re-verified (host variable, device variable length 1 and length 2)</td></tr></tbody></table><p>Rows marked &quot;not re-tested this run&quot; are not disproven — <code>probe/gpu/probe_gpu.jl</code> simply doesn&#39;t cover them yet; they carry forward <a href="/CTFlows.jl/previews/PR364/flows/gpu#What-runs-on-device">GPU flows</a>&#39; prior hardware validation without a fresh timestamp.</p><hr><h2 id="AD-backend-comparison-fresh-finding" tabindex="-1">AD backend comparison (fresh finding) <a class="header-anchor" href="#AD-backend-comparison-fresh-finding" aria-label="Permalink to &quot;AD backend comparison (fresh finding) {#AD-backend-comparison-fresh-finding}&quot;">​</a></h2><p>The probe exercises four AD backends across four call shapes: a plain gradient, the actual <code>Hamiltonian</code> gradient, a <strong>mutating</strong> in-place RHS, and the real <code>Flow(ocp)</code> Hamiltonian (which is in-place under the hood, via <code>CTModels</code>&#39; <code>dynamics!</code>):</p><table tabindex="0"><thead><tr><th style="text-align:right;">Backend</th><th style="text-align:center;">Plain gradient</th><th style="text-align:center;"><code>hamiltonian_gradient</code></th><th style="text-align:center;">Mutating in-place RHS</th><th style="text-align:center;"><code>Flow(ocp)</code> Hamiltonian</th></tr></thead><tbody><tr><td style="text-align:right;"><code>AutoForwardDiff</code> (CPU default)</td><td style="text-align:center;">✗ scalar indexing</td><td style="text-align:center;">✗ scalar indexing</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td></tr><tr><td style="text-align:right;"><code>AutoZygote</code></td><td style="text-align:center;">✓</td><td style="text-align:center;">✗ <code>KernelException</code></td><td style="text-align:center;">✗ can&#39;t differentiate <code>gc_preserve_end</code></td><td style="text-align:center;">✗ can&#39;t differentiate <code>gc_preserve_end</code></td></tr><tr><td style="text-align:right;"><code>AutoMooncake</code> (GPU default)</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td></tr><tr><td style="text-align:right;"><code>AutoEnzyme</code></td><td style="text-align:center;">✗ <code>EnzymeRuntimeActivityError</code></td><td style="text-align:center;">✗ <code>EnzymeMutabilityException</code></td><td style="text-align:center;">✓</td><td style="text-align:center;">✗ <code>EnzymeMutabilityException</code></td></tr></tbody></table><p><strong><code>AutoMooncake</code> is the only backend that survives every call shape measured on device</strong> — confirming it as the right <code>method=:gpu</code> default (already documented in <a href="/CTFlows.jl/previews/PR364/flows/gpu#AD-backends-on-device">GPU flows</a>).</p><p>Two refinements this run adds:</p><div class="tip custom-block"><p class="custom-block-title"><code>AutoZygote</code> breaks specifically once a call reduces over a device array</p><p>The plain gradient (no reduction inside the traced function beyond a final <code>sum</code>) works with <code>AutoZygote</code>. The moment the call chain goes through <code>CTBaseDifferentiationInterface.hamiltonian_gradient</code> (an extra <code>sum(abs2, …)</code> layer) or touches mutation, it fails — a <code>KernelException</code> in the first case, an inability to differentiate <code>gc_preserve_end</code> (a mutation-tracking marker) in the second. This is consistent with, and sharpens, the existing warning that <code>AutoZygote</code> &quot;is not reliably predictable&quot; on device.</p></div><div class="tip custom-block"><p class="custom-block-title"><code>AutoEnzyme</code> fails specifically on GPU array reductions, not on mutation itself</p><p>A synthetic mutating RHS with no reduction (<code>du .= 2 .* u</code>) differentiates fine with <code>AutoEnzyme</code>, on both host and device. But every failure above — <code>EnzymeRuntimeActivityError</code> on the plain gradient, <code>EnzymeMutabilityException</code> on <code>hamiltonian_gradient</code> and on <code>Flow(ocp)</code>&#39;s Hamiltonian — traces back to a <code>sum</code>/ <code>mapreduce</code> over a <code>CuArray</code> inside the traced function. Real Hamiltonians almost always contain such a reduction (<code>sum(abs2, x)</code>, <code>dot(p, x)</code>), so in practice <code>AutoEnzyme</code> is not currently usable for <code>Flow(::Hamiltonian)</code>/<code>Flow(ocp, ...)</code> on device — not a general &quot;Enzyme doesn&#39;t support GPU&quot; limitation, but this specific pattern.</p></div><hr><h2 id="Ensembles:-a-coupled-system-needs-the-kernel-path,-not-the-array-path" tabindex="-1">Ensembles: a coupled system needs the kernel path, not the array path <a class="header-anchor" href="#Ensembles:-a-coupled-system-needs-the-kernel-path,-not-the-array-path" aria-label="Permalink to &quot;Ensembles: a coupled system needs the kernel path, not the array path {#Ensembles:-a-coupled-system-needs-the-kernel-path,-not-the-array-path}&quot;">​</a></h2><p><a href="/CTFlows.jl/previews/PR364/flows/gpu#GPU-ensembles">GPU ensembles</a> already documents both DiffEqGPU.jl algorithms for a decoupled decay RHS (<code>du .= .-u</code>), where both work. This run adds a <strong>coupled</strong> oscillator (<code>du .= A * u</code>, a genuine matrix–vector product) to check whether that still holds:</p><table tabindex="0"><thead><tr><th style="text-align:right;">Algorithm</th><th style="text-align:center;">Decoupled (<code>du .= .-u</code>)</th><th style="text-align:center;">Coupled (<code>du .= A * u</code>)</th></tr></thead><tbody><tr><td style="text-align:right;"><code>EnsembleGPUArray</code> (in-place, host closures)</td><td style="text-align:center;">✓</td><td style="text-align:center;">✗ <code>InvalidIRError</code> (expected)</td></tr><tr><td style="text-align:right;"><code>EnsembleGPUKernel</code> (out-of-place <code>SVector</code>)</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td></tr></tbody></table><p>This matches <a href="/CTFlows.jl/previews/PR364/flows/gpu#⚠️-The-scalar-indexing-rule-inverts-here">GPU ensembles</a>&#39; own warning, now with a concrete failure: <code>EnsembleGPUArray</code>&#39;s in-place kernel cannot compile a BLAS matrix–vector product (<code>InvalidIRError</code>, as documented — kernels can&#39;t allocate or call BLAS), while <code>EnsembleGPUKernel</code>&#39;s out-of-place <code>SVector</code> RHS handles the coupled system correctly, since a small static matrix–vector product lowers to ordinary kernel code rather than a BLAS call.</p><hr><h2 id="See-also" tabindex="-1">See also <a class="header-anchor" href="#See-also" aria-label="Permalink to &quot;See also {#See-also}&quot;">​</a></h2><ul><li><p><a href="./../flows/gpu">GPU flows</a> — the full narrative guide: the GPU contract for your own code, <code>method=:gpu</code>, AD backend selection, ensembles, testing your own GPU code.</p></li><li><p><a href="./../dev/gpu-internals">GPU internals</a> — design decisions, the routing path, the coercion helpers.</p></li><li><p><a href="https://github.com/control-toolbox/CTFlows.jl/tree/main/probe/gpu" target="_blank" rel="noreferrer"><code>probe/gpu</code></a> — the probe this page is sourced from; re-run it (<code>run probe</code> label) to refresh this page.</p></li><li><p><a href="./overview">Compatibility overview</a> — the per-constructor feature matrix and the CPU compatibility pages.</p></li></ul>',24)])])}const u=t(d,[["render",i]]);export{p as __pageData,u as default};
